SELECT id, account_id, amount, txn_time, merchant, is_flagged, AVG(amount) OVER w_ordered AS amount_avg_5_prior, RANK() OVER (ORDER BY amount DESC NULLS LAST) AS amount_rank, ROUND(amount / SUM(amount) OVER (PARTITION BY account_id), 4) AS amount_share FROM transactions WINDOW w_ordered AS (PARTITION BY YEAR(txn_time), account_id ORDER BY amount, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING);
